/**
 * BiciStoreFaq
 *
 * FIXTURE DE TESTING. No es logica de negocio real.
 *
 * Accion invocable determinista para el subagente Faq del agente Bici Store.
 * Recibe la consulta del usuario, la normaliza, la tokeniza y busca la primera
 * clave que matchee segun un orden de prioridad EXPLICITO.
 *
 * Por que orden explicito: el orden de iteracion de un Map en Apex no esta
 * garantizado. Iterar el Map directamente haria no determinista el resultado
 * cuando una consulta matchea dos claves. Esta accion existe justamente para
 * ser el camino determinista del fixture, asi que las claves se recorren
 * usando la lista ORDEN_PRIORIDAD.
 *
 * No hace DML. No consulta la base de datos. Es pura.
 */
public with sharing class BiciStoreFaq {

    @TestVisible
    private static final String SIN_RESPUESTA = 'No tengo información sobre esa consulta.';

    /** Las 10 respuestas literales. No adornar: se asertan con string_assertion. */
    @TestVisible
    private static final Map<String, String> RESPUESTAS = new Map<String, String>{
        'horario'    => 'Abrimos de lunes a sábado de 9 a 19 horas.',
        'envio'      => 'El envío a domicilio demora entre 3 y 5 días hábiles.',
        'garantia'   => 'Todas las bicicletas tienen 12 meses de garantía.',
        'devolucion' => 'Aceptamos devoluciones dentro de los 30 días con la boleta.',
        'pago'       => 'Aceptamos efectivo, débito, crédito y transferencia.',
        'cuotas'     => 'Ofrecemos hasta 12 cuotas sin interés con tarjetas bancarias.',
        'sucursales' => 'Tenemos sucursales en Providencia, Ñuñoa y Las Condes.',
        'taller'     => 'El taller atiende sin cita previa de martes a viernes.',
        'armado'     => 'El armado de la bicicleta está incluido en la compra.',
        'stock'      => 'Podés consultar el stock disponible en nuestro sitio web.'
    };

    /**
     * Orden de evaluacion, de mas especifico a mas generico.
     * Cambiar este orden cambia el resultado de consultas ambiguas.
     * Si cambia, hay que actualizar BiciStoreFaqTest.testOrdenDePrioridad.
     */
    @TestVisible
    private static final List<String> ORDEN_PRIORIDAD = new List<String>{
        'cuotas',
        'garantia',
        'devolucion',
        'taller',
        'armado',
        'sucursales',
        'envio',
        'stock',
        'pago',
        'horario'
    };

    /**
     * Stems por clave. El match es token.startsWith(stem) sobre texto normalizado
     * (minusculas, sin acentos, sin puntuacion), asi que los stems cubren plurales
     * y conjugaciones sin listarlos: 'sucursal' cubre 'sucursales'.
     */
    @TestVisible
    private static final Map<String, List<String>> STEMS = new Map<String, List<String>>{
        'cuotas'     => new List<String>{ 'cuota' },
        'garantia'   => new List<String>{ 'garantia' },
        'devolucion' => new List<String>{ 'devolucion', 'devolver', 'devuelv' },
        'taller'     => new List<String>{ 'taller', 'reparacion', 'reparar', 'arreglar', 'arreglan' },
        'armado'     => new List<String>{ 'arma' },
        'sucursales' => new List<String>{ 'sucursal', 'local', 'tienda' },
        'envio'      => new List<String>{ 'envio', 'envia', 'enviar', 'despacho', 'despachan' },
        'stock'      => new List<String>{ 'stock', 'disponib' },
        'pago'       => new List<String>{ 'pago', 'pagos', 'pagar', 'pagan', 'efectivo', 'tarjeta', 'debito', 'credito', 'transferencia' },
        'horario'    => new List<String>{ 'horario', 'abren', 'abre', 'cierran', 'cierra', 'atienden' }
    };

    @InvocableMethod(
        label='Bici Store FAQ'
        description='Responde preguntas frecuentes de la tienda de bicicletas sobre horario, envio, garantia, devoluciones, medios de pago, cuotas, sucursales, taller, armado y stock. Devuelve una respuesta fija. No sirve para consultar el estado de un pedido puntual ni el precio de un modelo especifico.'
        category='Bici Store'
    )
    public static List<Output> responder(List<Input> inputs) {
        List<Output> salidas = new List<Output>();
        if (inputs == null) {
            return salidas;
        }
        for (Input entrada : inputs) {
            Output salida = new Output();
            salida.respuesta = buscar(entrada == null ? null : entrada.consulta);
            salidas.add(salida);
        }
        return salidas;
    }

    /** Logica pura, expuesta para poder testearla sin armar wrappers. */
    @TestVisible
    private static String buscar(String consulta) {
        if (String.isBlank(consulta)) {
            return SIN_RESPUESTA;
        }

        Set<String> tokens = tokenizar(normalizar(consulta));
        if (tokens.isEmpty()) {
            return SIN_RESPUESTA;
        }

        for (String clave : ORDEN_PRIORIDAD) {
            for (String stem : STEMS.get(clave)) {
                for (String token : tokens) {
                    if (token.startsWith(stem)) {
                        return RESPUESTAS.get(clave);
                    }
                }
            }
        }
        return SIN_RESPUESTA;
    }

    /** Minusculas y sin acentos. La salida NUNCA se normaliza, solo la entrada. */
    @TestVisible
    private static String normalizar(String texto) {
        return texto.toLowerCase()
            .replace('á', 'a').replace('à', 'a').replace('ä', 'a').replace('â', 'a')
            .replace('é', 'e').replace('è', 'e').replace('ë', 'e').replace('ê', 'e')
            .replace('í', 'i').replace('ì', 'i').replace('ï', 'i').replace('î', 'i')
            .replace('ó', 'o').replace('ò', 'o').replace('ö', 'o').replace('ô', 'o')
            .replace('ú', 'u').replace('ù', 'u').replace('ü', 'u').replace('û', 'u')
            .replace('ñ', 'n');
    }

    /** Todo lo que no sea letra o digito pasa a ser separador. */
    @TestVisible
    private static Set<String> tokenizar(String textoNormalizado) {
        Set<String> tokens = new Set<String>();
        for (String pieza : textoNormalizado.replaceAll('[^a-z0-9]+', ' ').split(' ')) {
            if (String.isNotBlank(pieza)) {
                tokens.add(pieza);
            }
        }
        return tokens;
    }

    public class Input {
        @InvocableVariable(
            label='Consulta'
            description='Texto literal de la consulta del cliente.'
            required=false
        )
        public String consulta;
    }

    public class Output {
        @InvocableVariable(
            label='Respuesta'
            description='Respuesta fija de la tienda, o el texto de fallback si la consulta no matchea ninguna clave conocida.'
        )
        public String respuesta;
    }
}

/**
 * BiciStoreFaqTest
 *
 * Cubre BiciStoreFaq. Sin DML, sin SeeAllData, sin datos de prueba:
 * la clase bajo test es pura.
 *
 * Los asserts usan los strings literales tal como los va a asertar el repo
 * de testing con string_assertion. Si un literal cambia aca, tiene que cambiar
 * tambien en el repo de tests.
 */
@IsTest
private class BiciStoreFaqTest {

    private static final String SIN_RESPUESTA = 'No tengo información sobre esa consulta.';

    /** Helper: arma el wrapper, invoca la accion y devuelve la respuesta. */
    private static String preguntar(String consulta) {
        BiciStoreFaq.Input entrada = new BiciStoreFaq.Input();
        entrada.consulta = consulta;
        List<BiciStoreFaq.Output> salidas =
            BiciStoreFaq.responder(new List<BiciStoreFaq.Input>{ entrada });
        System.assertEquals(1, salidas.size(), 'Debe devolver una salida por entrada');
        return salidas[0].respuesta;
    }

    @IsTest
    static void testLasDiezRespuestasLiterales() {
        Test.startTest();
        System.assertEquals(
            'Abrimos de lunes a sábado de 9 a 19 horas.',
            preguntar('¿Cuál es el horario de la tienda?'),
            'horario');
        System.assertEquals(
            'El envío a domicilio demora entre 3 y 5 días hábiles.',
            preguntar('¿Cuánto demora el envío?'),
            'envio');
        System.assertEquals(
            'Todas las bicicletas tienen 12 meses de garantía.',
            preguntar('¿Qué garantía tienen las bicis?'),
            'garantia');
        System.assertEquals(
            'Aceptamos devoluciones dentro de los 30 días con la boleta.',
            preguntar('¿Puedo hacer una devolución?'),
            'devolucion');
        System.assertEquals(
            'Aceptamos efectivo, débito, crédito y transferencia.',
            preguntar('¿Qué medios de pago aceptan?'),
            'pago');
        System.assertEquals(
            'Ofrecemos hasta 12 cuotas sin interés con tarjetas bancarias.',
            preguntar('¿Se puede en cuotas?'),
            'cuotas');
        System.assertEquals(
            'Tenemos sucursales en Providencia, Ñuñoa y Las Condes.',
            preguntar('¿Dónde tienen sucursales?'),
            'sucursales');
        System.assertEquals(
            'El taller atiende sin cita previa de martes a viernes.',
            preguntar('¿El taller necesita cita?'),
            'taller');
        System.assertEquals(
            'El armado de la bicicleta está incluido en la compra.',
            preguntar('¿El armado tiene costo?'),
            'armado');
        System.assertEquals(
            'Podés consultar el stock disponible en nuestro sitio web.',
            preguntar('¿Tienen stock?'),
            'stock');
        Test.stopTest();
    }

    @IsTest
    static void testFallbackExacto() {
        Test.startTest();
        System.assertEquals(SIN_RESPUESTA, preguntar('¿Cuánto sale la Trek Marlin 5?'),
            'Precio de un modelo especifico no debe matchear ninguna clave');
        System.assertEquals(SIN_RESPUESTA, preguntar('Quiero hablar con un vendedor'),
            'Pedido de vendedor no debe matchear');
        Test.stopTest();
    }

    /**
     * El par de borde del fixture. "Donde esta mi pedido" rutea a Escalar y no
     * deberia llegar nunca a esta accion, pero si llega tiene que caer al
     * fallback y no confundirse con la respuesta de envio.
     */
    @IsTest
    static void testParDeBorde() {
        Test.startTest();
        System.assertEquals(
            'El envío a domicilio demora entre 3 y 5 días hábiles.',
            preguntar('¿Cuánto demora el envío?'),
            'Proceso general de envio: matchea');
        System.assertEquals(
            SIN_RESPUESTA,
            preguntar('¿Dónde está mi pedido?'),
            'Estado de un pedido puntual: NO matchea');
        Test.stopTest();
    }

    @IsTest
    static void testEntradasVacias() {
        Test.startTest();
        System.assertEquals(SIN_RESPUESTA, preguntar(null), 'null cae al fallback');
        System.assertEquals(SIN_RESPUESTA, preguntar(''), 'vacio cae al fallback');
        System.assertEquals(SIN_RESPUESTA, preguntar('   '), 'blanco cae al fallback');
        System.assertEquals(SIN_RESPUESTA, preguntar('¿¿¿ !!! ???'),
            'solo puntuacion cae al fallback');
        Test.stopTest();
    }

    @IsTest
    static void testSinAcentosYMayusculas() {
        Test.startTest();
        System.assertEquals(
            'El envío a domicilio demora entre 3 y 5 días hábiles.',
            preguntar('CUANTO DEMORA EL ENVIO'),
            'Mayusculas y sin acentos deben matchear igual');
        System.assertEquals(
            'Tenemos sucursales en Providencia, Ñuñoa y Las Condes.',
            preguntar('tienen sucursal en Ñuñoa?'),
            'La enie en la entrada se normaliza; la salida conserva Ñuñoa');
        Test.stopTest();
    }

    /** 'ahora' contiene 'hora' pero el match es por token, no por substring. */
    @IsTest
    static void testNoMatcheaPorSubstring() {
        Test.startTest();
        System.assertEquals(SIN_RESPUESTA, preguntar('quiero comprar ahora'),
            '"ahora" no debe disparar horario');
        Test.stopTest();
    }

    /**
     * Consultas ambiguas resueltas por ORDEN_PRIORIDAD.
     * Si cambia el orden en BiciStoreFaq, este test falla a proposito.
     */
    @IsTest
    static void testOrdenDePrioridad() {
        Test.startTest();
        System.assertEquals(
            'Ofrecemos hasta 12 cuotas sin interés con tarjetas bancarias.',
            preguntar('¿Puedo pagar en cuotas con tarjeta?'),
            'cuotas gana sobre pago');
        System.assertEquals(
            'El taller atiende sin cita previa de martes a viernes.',
            preguntar('¿En qué horario abre el taller?'),
            'taller gana sobre horario');
        System.assertEquals(
            'El armado de la bicicleta está incluido en la compra.',
            preguntar('¿El envío incluye el armado?'),
            'armado gana sobre envio');
        Test.stopTest();
    }

    @IsTest
    static void testBulk() {
        List<BiciStoreFaq.Input> entradas = new List<BiciStoreFaq.Input>();
        for (String consulta : new List<String>{
                '¿Cuál es el horario?', '¿Cuánto demora el envío?',
                '¿Qué garantía tiene?', 'no se que preguntar' }) {
            BiciStoreFaq.Input entrada = new BiciStoreFaq.Input();
            entrada.consulta = consulta;
            entradas.add(entrada);
        }

        Test.startTest();
        List<BiciStoreFaq.Output> salidas = BiciStoreFaq.responder(entradas);
        Test.stopTest();

        System.assertEquals(4, salidas.size(), 'Una salida por entrada, en orden');
        System.assertEquals('Abrimos de lunes a sábado de 9 a 19 horas.', salidas[0].respuesta);
        System.assertEquals('El envío a domicilio demora entre 3 y 5 días hábiles.', salidas[1].respuesta);
        System.assertEquals('Todas las bicicletas tienen 12 meses de garantía.', salidas[2].respuesta);
        System.assertEquals(SIN_RESPUESTA, salidas[3].respuesta);
    }

    @IsTest
    static void testEntradasNulas() {
        Test.startTest();
        System.assertEquals(0, BiciStoreFaq.responder(null).size(),
            'Lista null devuelve lista vacia, no explota');
        List<BiciStoreFaq.Output> salidas =
            BiciStoreFaq.responder(new List<BiciStoreFaq.Input>{ null });
        Test.stopTest();

        System.assertEquals(1, salidas.size());
        System.assertEquals(SIN_RESPUESTA, salidas[0].respuesta, 'Input null cae al fallback');
    }

    /** Las 10 claves tienen respuesta y stems. Guarda contra ediciones parciales. */
    @IsTest
    static void testIntegridadDelMapa() {
        Test.startTest();
        System.assertEquals(10, BiciStoreFaq.RESPUESTAS.size(), 'Deben ser 10 respuestas');
        System.assertEquals(10, BiciStoreFaq.ORDEN_PRIORIDAD.size(), 'Deben ser 10 claves ordenadas');
        for (String clave : BiciStoreFaq.ORDEN_PRIORIDAD) {
            System.assert(BiciStoreFaq.RESPUESTAS.containsKey(clave),
                'Clave sin respuesta: ' + clave);
            System.assert(BiciStoreFaq.STEMS.containsKey(clave),
                'Clave sin stems: ' + clave);
        }
        Test.stopTest();
    }
}
